import sys, re, json, glob, importlib, shutil, os, subprocess
from pathlib import Path
A=Path('/app')
def runs():
    out=[]; starts={}
    for f in sorted(glob.glob('/app/logs/sched/*.log')):
        for l in open(f):
            p=l.split()
            if p[1]=='start':
                d=dict(x.split('=',1) for x in p[3:]); starts[d['run']]=(p[0],p[2],d)
            elif p[1]=='end' and 'exit=0' in l:
                d=dict(x.split('=',1) for x in p[3:]); s=starts[d['run']]
                out.append(dict(now=s[0],job=s[2:] and s[1],loaded=s[2]['loaded'],feed=s[2].get('feed'),wrote=d['wrote'],ver=s[2]['version']))
    return out
def snaps():
    return sorted(os.listdir('/app/var/snapshots'), key=lambda n:(n.split('-')[1],n))
def load_pkg(root):
    for m in [m for m in sys.modules if m.startswith('spokehouse')]: del sys.modules[m]
    sys.path.insert(0,root)
    import spokehouse, spokehouse.jobs, spokehouse.feeds, spokehouse.timeutil, spokehouse.store
    sys.path.pop(0); return spokehouse
def analyze(root, lost=False):
    pkg=load_pkg(root); order=snaps(); res=[]
    for r in runs():
        if r['ver']!='4.2.0': continue
        w=order.index(r['wrote']); prev=order[w-1]
        inp = prev if (lost and prev!=r['loaded']) else r['loaded']
        st=pkg.store.load('/app/var/snapshots/'+inp)
        feed='/app/'+r['feed'] if r['feed'] else None
        mod=pkg.jobs.JOBS[r['job']]
        batch=pkg.feeds.read_batch(feed) if mod.FEED else None
        new=mod.run(st,batch,pkg.timeutil.parse_ts(r['now']))
        act=pkg.store.load('/app/var/snapshots/'+r['wrote'])
        if pkg.store.data(new)!=pkg.store.data(act): res.append(r['wrote'])
    return res
if __name__=='__main__':
    print(len(analyze(sys.argv[1], len(sys.argv)>2)))
