import glob,json,re
runs={}
for f in sorted(glob.glob('/app/logs/sched/*.log')):
    for l in open(f):
        p=l.split()
        if p[1]=='start':
            d=dict(x.split('=',1) for x in p[3:]); runs[d['run']]=dict(id=d['run'],job=p[2],start=p[0],feed=d.get('feed'))
